<script lang="ts">
  import { onMount, onDestroy, type Snippet } from 'svelte';
  import Panel from './Panel.svelte'; import Icon from '#lib/components/Icon.svelte';
  import { number as n, text, rows, type Row, type Model, type Actions } from './model';
  import { apiGet, apiPatch } from '#lib/api/client.ts';
  import { uploadAttachment, fetchAttachmentBlob } from '#lib/api/attachments.ts';
  import { analyzeAttachment } from '#lib/api/receipts.ts';
  import { getParsers, uploadImport, previewImport as previewBankImport, confirmImport, getImportHistory, undoImport, type ImportSession, type ParserInfo, type ImportPreview as BankPreview } from '#lib/api/imports.ts';
  import { exportBackup, previewImport as previewBackup, importBackup, type ImportPreview } from '#lib/api/backup.ts';
  let { m, a, children }: { m: Model; a: Actions; children: Snippet } = $props();
  let importHistory=$state<ImportSession[]>([]);let undoTarget=$state<number|null>(null);const attachments=$derived(m.attachments);
  let busy=$state(false); let error=$state(''); let selected=$state<Row | null>(null); let previewUrl=$state(''); let receiptFilter=$state('');
  let merchant=$state(''); let receiptDate=$state(''); let total=$state<number | undefined>(); let subtotal=$state<number | undefined>(); let tax=$state<number | undefined>();
  let parsers=$state<ParserInfo[]>([]); let parser=$state('generic'); let account=$state(''); let category=$state(''); let bankPreview=$state<BankPreview | null>(null); let selectedIndexes=$state<number[]>([]);
  let backupFile=$state<unknown>(); let backupPreview=$state<ImportPreview | null>(null); let backupName=$state('');
  onMount(()=>{if(m.route==='importar')void getImportHistory().then(value=>importHistory=value).catch(report);if(m.route==='recibos'&&m.receipts[0])void selectReceipt(m.receipts[0]);if(m.route==='importar')void getParsers().then(result=>parsers=result).catch(report);});
  let receiptRequest=0;
  onDestroy(()=>{receiptRequest++;if(previewUrl)URL.revokeObjectURL(previewUrl);});
  function report(e:unknown){error=e instanceof Error?e.message:String(e);}
  async function selectReceipt(row:Row){
    const request=++receiptRequest;
    error=''; selected=null;
    if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl='';}
    try{
      const value=await apiGet<Record<string,unknown>>(`/receipts/${row.id}`);
      if(request!==receiptRequest)return;
      let nextUrl='';
      if(value.attachmentId){const blob=await fetchAttachmentBlob(n(value.attachmentId));if(request!==receiptRequest)return;nextUrl=URL.createObjectURL(blob);}
      selected={...value,id:n(value.id)};merchant=text(value.merchant);receiptDate=text(value.receiptDate).slice(0,10);total=n(value.total);subtotal=value.subtotal==null?undefined:n(value.subtotal);tax=value.tax==null?undefined:n(value.tax);previewUrl=nextUrl;
    }catch(e){if(request===receiptRequest)report(e);}
  }
  async function uploadReceipt(event:Event){const files=(event.target as HTMLInputElement).files;if(!files?.length)return;busy=true;error='';try{for(const file of Array.from(files)){const attachment=await uploadAttachment(file);await analyzeAttachment(attachment.id);}await a.refresh();a.notify(m.t('cyberpunk.receipts_uploaded'));}catch(e){report(e);}finally{busy=false;}}
  async function saveReceipt(event:SubmitEvent){event.preventDefault();if(!selected)return;busy=true;try{await apiPatch(`/receipts/${selected.id}`,{merchant,receiptDate:receiptDate||null,total,subtotal,tax});await a.refresh();a.notify(m.t('cyberpunk.receipt_saved'));}catch(e){report(e);}finally{busy=false;}}
  async function uploadBank(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;busy=true;error='';try{const session=await uploadImport(file,{parser,accountId:account?n(account):undefined});bankPreview=await previewBankImport(session.id);selectedIndexes=bankPreview.transactions.filter(row=>row.status==='new').map(row=>row.index);if(bankPreview.detectedAccountId)account=text(bankPreview.detectedAccountId);}catch(e){report(e);}finally{busy=false;(event.target as HTMLInputElement).value='';}}
  async function importBank(){if(!bankPreview||!account)return;busy=true;error='';try{const result=await confirmImport(bankPreview.sessionId,{accountId:n(account),defaultCategoryId:category?n(category):undefined,selectedTransactionIds:selectedIndexes});bankPreview=null;importHistory=await getImportHistory();await a.refresh();a.notify(`${result.importedCount} ${m.t('cyberpunk.transactions_imported')}`);}catch(e){report(e);}finally{busy=false;}}
  async function undo(){if(undoTarget==null)return;busy=true;try{await undoImport(undoTarget);undoTarget=null;importHistory=await getImportHistory();await a.refresh();}catch(e){report(e);}finally{busy=false;}}
  async function analyze(id:number){busy=true;try{await analyzeAttachment(id);await a.refresh();}catch(e){report(e);}finally{busy=false;}}
  async function download(){busy=true;error='';try{const backup=await exportBackup();const url=URL.createObjectURL(new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`homeledger-${new Date().toISOString().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);await a.refresh();}catch(e){report(e);}finally{busy=false;}}
  async function chooseBackup(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;busy=true;error='';try{backupFile=JSON.parse(await file.text());backupPreview=await previewBackup(backupFile);backupName=file.name;}catch(e){report(e);}finally{busy=false;}}
  async function restore(){busy=true;error='';try{await importBackup(backupFile,true);backupPreview=null;backupFile=undefined;await a.refresh();a.notify(m.t('cyberpunk.backup_restored'));}catch(e){report(e);}finally{busy=false;}}
</script>
{#if error}<p class="cp-error" role="alert">{error}</p>{/if}
{#if m.route === 'configuracion'}
  <div class="cp-settings">{@render children()}</div>
{:else if m.route === 'recibos'}
  <div class="cp-toolbar"><button class="cp-button" onclick={()=>a.edit('receipts')}>{m.t('cyberpunk.attach_scan_receipt')}</button><input aria-label={m.t('cyberpunk.filter_receipts')} bind:value={receiptFilter} placeholder={m.t('cyberpunk.search_receipts')}/><label class="cp-button cp-file-button">+ {busy?'…':m.t('dashboard.upload_receipt_btn')}<input type="file" multiple accept="image/*,application/pdf,text/xml,application/xml" disabled={busy} onchange={uploadReceipt}/></label></div>
  <div class="cp-receipts-layout"><Panel title={m.t('cyberpunk.my_receipts')}><div class="cp-receipt-list">{#each m.receipts.filter(row=>`${text(row.merchant)} ${text(row.filename)}`.toLowerCase().includes(receiptFilter.toLowerCase())) as row}<button class:active={selected?.id===row.id} onclick={()=>selectReceipt(row)}><span class="cp-receipt-thumb"><Icon name="file-text" size={32}/></span><span><strong>{text(row.merchant)||text(row.filename)||m.t('cyberpunk.receipt')}</strong><small>{m.date(row.receiptDate)}</small><b class="cp-number">{m.money(row.total)}</b></span></button>{:else}<p class="cp-empty">{m.t('cyberpunk.upload_a_receipt_to_see_its_extracted_details')}</p>{/each}</div></Panel><Panel title={m.t('cyberpunk.receipt_details')}>
    {#if selected}<div class="cp-receipt-detail"><div class="cp-document">{#if previewUrl&&text(selected.mimeType).startsWith('image/')}<img src={previewUrl} alt={m.t('cyberpunk.uploaded_receipt')}/>{:else if previewUrl&&selected.mimeType==='application/pdf'}<iframe src={previewUrl} title={m.t('cyberpunk.receipt_pdf_preview')}></iframe>{:else}<div class="cp-paper"><h3>{merchant}</h3><p>{m.date(receiptDate)}</p><pre>{text(selected.rawText)||text(selected.filename)}</pre><strong>{m.money(total)}</strong></div>{/if}</div><form class="cp-form" onsubmit={saveReceipt}><label>{m.t('transactions.merchant')}<input bind:value={merchant}/></label><label>{m.t('receipts.form_date')}<input type="date" bind:value={receiptDate}/></label><div class="cp-two"><label>{m.t('receipts.field_subtotal')}<input type="number" step="0.01" bind:value={subtotal}/></label><label>{m.t('receipts.field_tax')}<input type="number" step="0.01" bind:value={tax}/></label></div><div class="cp-extracted-total"><span>{m.t('common.total')}</span><strong>{m.money(total)}</strong></div><label>{m.t('cyberpunk.corrected_total')}<input type="number" step="0.01" bind:value={total}/></label><div class="cp-table-wrap"><table class="cp-table"><thead><tr><th>{m.t('cyberpunk.item')}</th><th>{m.t('cyberpunk.quantity')}</th><th>{m.t('common.total')}</th></tr></thead><tbody>{#each rows(selected.items) as item}<tr><td>{text(item.description)}</td><td>{n(item.quantity)}</td><td>{m.money(item.total)}</td></tr>{/each}</tbody></table></div><button class="cp-button" disabled={busy}>{m.t('cyberpunk.save_receipt')}</button><button class="cp-button ghost" type="button" onclick={()=>a.edit('receipts',selected??undefined)}>{m.t('cyberpunk.link_transaction_edit_items')}</button></form></div>{:else}<div class="cp-receipt-placeholder"><Icon name="file-text" size={68}/><p>{m.t('cyberpunk.choose_a_receipt_to_review_its_original_document_and_extracted_data')}</p></div>{/if}
  </Panel></div>
  {#if attachments.some(file=>!m.receipts.some(receipt=>receipt.attachmentId===file.id))}<Panel title={m.t('cyberpunk.pending_documents')}>{#each attachments.filter(file=>!m.receipts.some(receipt=>receipt.attachmentId===file.id)) as file}<div class="cp-card-footer"><span>{file.originalName||file.filename}</span><button class="cp-button ghost small" disabled={busy} onclick={()=>analyze(file.id)}>{m.t('receipts.analyze')}</button></div>{/each}</Panel>{/if}
{:else if m.route === 'importar'}
  <Panel title={m.t('cyberpunk.import_transactions')}><ol class="cp-steps"><li class="active">1 {m.t('cyberpunk.upload_file')}</li><li class:active={Boolean(bankPreview)}>2 {m.t('backup.preview_title')}</li><li>3 {m.t('common.confirm')}</li></ol><div class="cp-import-layout"><div class="cp-form"><label>{m.t('cyberpunk.bank_format')}<select bind:value={parser}>{#each parsers as row}<option value={row.bankId}>{row.bankId==='generic'?m.t('cyberpunk.generic_csv'):row.bankName}</option>{/each}</select></label><label>{m.t('cyberpunk.destination_account')}<select bind:value={account}><option value="">{m.t('subscriptions.form_account_placeholder')}</option>{#each m.accounts as row}<option value={text(row.id)}>{text(row.name)}</option>{/each}</select></label><label>{m.t('cyberpunk.default_category')}<select bind:value={category}><option value="">{m.t('cyberpunk.automatic')}</option>{#each m.categories as row}<option value={text(row.id)}>{text(row.name)}</option>{/each}</select></label></div><label class="cp-dropzone"><Icon name="upload" size={42}/><strong>{bankPreview?.filename||m.t('cyberpunk.choose_your_bank_statement')}</strong><span>{m.t('cyberpunk.csv_excel_or_supported_bank_format')}</span><span class="cp-button ghost">{busy?'…':m.t('import.select_file')}</span><input type="file" accept=".csv,.xlsx,.xls,.txt" disabled={busy} onchange={uploadBank}/></label></div></Panel>
  {#if bankPreview}<Panel title={`${m.t('backup.preview_title')} (${bankPreview.totalCount})`}><p class="cp-muted">{bankPreview.newCount} {m.t('cyberpunk.new')} · {bankPreview.duplicateCount} {m.t('cyberpunk.duplicates')}</p><div class="cp-table-wrap"><table class="cp-table"><thead><tr><th><span class="cp-sr">{m.t('cyberpunk.select')}</span></th><th>{m.t('receipts.form_date')}</th><th>{m.t('dashboard.description')}</th><th>{m.t('receipts.form_amount')}</th><th>{m.t('common.status')}</th></tr></thead><tbody>{#each bankPreview.transactions as row}<tr><td><input type="checkbox" aria-label={row.description} checked={selectedIndexes.includes(row.index)} onchange={(event)=>selectedIndexes=event.currentTarget.checked?[...selectedIndexes,row.index]:selectedIndexes.filter(i=>i!==row.index)}/></td><td>{m.date(row.normalizedDate||row.date)}</td><td>{row.description}</td><td class="cp-number" class:cp-red={row.type==='expense'} class:cp-cyan={row.type==='income'}>{row.type==='expense'?'−':'+'}{m.money(row.amount)}</td><td>{row.status}</td></tr>{/each}</tbody></table></div><footer class="cp-card-footer"><span>{selectedIndexes.length} {m.t('cyberpunk.selected')}</span><button class="cp-button" disabled={busy||!account||!selectedIndexes.length} onclick={importBank}>{m.t('cyberpunk.import_selected_transactions')} →</button></footer></Panel>{/if}
  <Panel title={m.t('import.history_title')}><div class="cp-table-wrap"><table class="cp-table"><thead><tr><th>{m.t('receipts.form_date')}</th><th>{m.t('receipts.upload_file')}</th><th>{m.t('common.status')}</th><th></th></tr></thead><tbody>{#each importHistory as row}<tr><td>{m.date(row.createdAt)}</td><td>{row.filename}</td><td>{row.status}</td><td>{#if row.status==='completed'}<button class="cp-button ghost small" onclick={()=>undoTarget=row.id}>{m.t('cyberpunk.undo_import')}</button>{/if}</td></tr>{:else}<tr><td colspan="4" class="cp-empty">{m.t('cyberpunk.no_imports_yet')}</td></tr>{/each}</tbody></table></div>{#if undoTarget!=null}<p>{m.t('cyberpunk.remove_the_transactions_created_by_this_import')}</p><div class="cp-form-actions"><button class="cp-button ghost" onclick={()=>undoTarget=null}>{m.t('receipts.cancel')}</button><button class="cp-button danger" disabled={busy} onclick={undo}>{m.t('cyberpunk.confirm_undo')}</button></div>{/if}</Panel><a class="cp-link" href="/respaldo">{m.t('cyberpunk.import_or_export_a_json_backup')} →</a>
{:else}
  <div class="cp-two"><Panel title={m.t('cyberpunk.export_backup')}><div class="cp-backup-action"><Icon name="database" size={45}/><p>{m.t('cyberpunk.download_a_json_file_with_your_accounts_transactions_categories_budgets_and_goals')}</p><button class="cp-button" disabled={busy} onclick={download}>↓ {m.t('cyberpunk.download_json')}</button></div></Panel><Panel title={m.t('cyberpunk.import_backup')}><label class="cp-dropzone"><Icon name="upload" size={38}/><strong>{m.t('cyberpunk.restore_a_homeledger_backup')}</strong><span>{m.t('cyberpunk.select_a_json_file_to_preview_its_contents_first')}</span><span class="cp-button ghost">{m.t('import.select_file')}</span><input type="file" accept=".json,application/json" disabled={busy} onchange={chooseBackup}/></label></Panel></div>
  {#if backupPreview}<Panel title={m.t('cyberpunk.confirm_restore')}><p>{backupName}</p><p class="cp-red">{m.t('cyberpunk.importing_replaces_all_financial_data_for_this_account_review_the_counts_before_continuing')}</p><div class="cp-stats plain">{#each Object.entries(backupPreview.backupCounts).filter(([,count])=>count>0) as [key,count]}<div class="cp-stat"><span>{key}</span><strong>{count}</strong></div>{/each}</div>{#each backupPreview.warnings as warning}<p class="cp-error">{warning}</p>{/each}<div class="cp-form-actions"><button class="cp-button ghost" onclick={()=>backupPreview=null}>{m.t('receipts.cancel')}</button><button class="cp-button danger" disabled={busy} onclick={restore}>{m.t('cyberpunk.replace_data_and_restore')}</button></div></Panel>{/if}
  <Panel title={m.t('cyberpunk.backup_history')}><div class="cp-table-wrap"><table class="cp-table"><thead><tr><th>{m.t('receipts.form_date')}</th><th>{m.t('cyberpunk.operation')}</th></tr></thead><tbody>{#each m.backupHistory as row}<tr><td>{m.date(row.createdAt)}</td><td>{row.type==='export'?m.t('backup.type_export'):m.t('backup.type_import')}</td></tr>{:else}<tr><td colspan="2" class="cp-empty">{m.t('cyberpunk.your_backup_activity_will_appear_here')}</td></tr>{/each}</tbody></table></div></Panel><a class="cp-link" href="/configuracion">{m.t('cyberpunk.manage_scheduled_snapshots_in_settings')} →</a>
{/if}
